<script setup>
import {ref,computed} from 'vue'
import {sqlModel,pathModel,htmlModel} from './models.js'
import EvidenceLens from './EvidenceLens.vue'
const kind=ref('sql'),input=ref('Books'),safe=ref(false),snapshot=ref(null),baseline=ref(null),history=ref([])
let sequence=0
const settings={sql:{title:'A query built from text',presets:['Books',"Books'","Books' OR '1'='1'-- "],label:'Category value'},path:{title:'A file path without a boundary',presets:['cat.png','../notes.txt','%2e%2e%2fnotes.txt'],label:'Requested filename'},html:{title:'Text meets the HTML parser',presets:['hello','<strong>hello</strong>','<img src=x onerror="demo()">'],label:'Search text'}}
const config=computed(()=>settings[kind.value])
const dirty=computed(()=>snapshot.value&&snapshot.value.values.input!==input.value)
function run(){const result=({sql:sqlModel,path:pathModel,html:htmlModel})[kind.value](input.value,safe.value);snapshot.value={id:++sequence,values:{input:input.value},safe:safe.value,result,label:safe.value?'Boundary enforced':'Input experiment'};if(!safe.value&&input.value===config.value.presets[0])baseline.value=snapshot.value;history.value=[snapshot.value,...history.value].slice(0,5)}
function change(){input.value=config.value.presets[0];snapshot.value=null;baseline.value=null;history.value=[];sequence=0}
</script>
<template><section class="sandbox"><div class="sandbox-heading"><div class="eyebrow">TRY AN EXAMPLE OR TYPE · LOCAL MODEL</div><h2>Watch the interpretation change.</h2><p>Three deliberately small models. Their visuals show local interpretation, with no script execution or external requests.</p></div><div class="filter-row"><label class="select-label">Model<select v-model="kind" @change="change"><option value="sql">SQL expression</option><option value="path">Path resolution</option><option value="html">HTML parsing</option></select></label><label class="safe-toggle"><input type="checkbox" v-model="safe" @change="run"> Enforce the boundary</label></div><h3>{{config.title}}</h3><div class="preset-list"><button v-for="(p,i) in config.presets" :key="p" class="button" @click="input=p;run()">{{['Normal input','Boundary probe','Variation'][i]}}</button></div><div class="playground-grid"><form @submit.prevent="run"><label for="sandbox-input">{{config.label}}</label><textarea id="sandbox-input" v-model="input" maxlength="3000" rows="4" spellcheck="false"></textarea><button class="button primary" type="submit">Run the model →</button><p v-if="dirty" class="draft-notice" role="status">Unsent changes. The inspector still shows request #{{snapshot.id}}.</p><p v-if="snapshot" class="playground-explanation">{{snapshot.result.explanation}}</p></form><EvidenceLens :context="kind" :snapshot="snapshot" :baseline="baseline" :history="history" :fields="[{key:'input',label:config.label}]" /></div></section></template>
